def asignar_playlists_antiguas(apps, schema_editor):
    """
    Las playlists creadas antes del login no tienen dueño. Si ya existe un
    superusuario se le asignan; si no, quedan sin dueño y solo las ven los
    administradores.
    """
    Playlist = apps.get_model('productos', 'Playlist')
    User = apps.get_model('auth', 'User')
    admin = User.objects.filter(is_superuser=True).order_by('id').first()
    if admin:
        Playlist.objects.filter(propietario__isnull=True).update(propietario=admin)


